import sys
import types

try:
    import torch
except ModuleNotFoundError:
    # Minimal stand-in for the few torch features used here (torch is not installed in this sandbox).
    import numpy as np

    class Tensor:
        def __init__(self, data):
            self.data = np.array(data, dtype=np.float64)

        def clone(self):
            return Tensor(self.data.copy())

        def __add__(self, other):
            return Tensor(self.data + other.data)

        def __truediv__(self, n):
            return Tensor(self.data / n)

        def __len__(self):
            return len(self.data)

        def __repr__(self):
            def fmt(v):
                return f"{int(v)}." if float(v).is_integer() else f"{v:.4f}"
            return "tensor([" + ", ".join(fmt(v) for v in self.data) + "])"

    torch = types.ModuleType("torch")
    torch.Tensor = Tensor
    torch.tensor = lambda data: Tensor(data)
    torch.allclose = lambda a, b: bool(np.allclose(a.data, b.data))
    sys.modules["torch"] = torch


def all_reduce_avg(gradients: list["torch.Tensor"]) -> list["torch.Tensor"]:
    """Simulate AllReduce: average all gradient tensors and return
    a list where every element is the averaged tensor."""
    total = gradients[0].clone()
    for g in gradients[1:]:
        total = total + g
    avg = total / len(gradients)
    return [avg.clone() for _ in gradients]


# Test
g0 = torch.tensor([1.0, 2.0, 3.0])
g1 = torch.tensor([3.0, 4.0, 5.0])
result = all_reduce_avg([g0, g1])
print(result[0])  # tensor([2., 3., 4.])
print(result[1])  # tensor([2., 3., 4.])
